<?php
if (!isset($midterm) || !is_array($midterm)) throw new RuntimeException('Midterm report data is unavailable.');
if (!function_exists('midterm_escape')) {
    function midterm_escape($value) { return htmlspecialchars((string)$value,ENT_QUOTES | ENT_SUBSTITUTE,'UTF-8'); }
    function midterm_mark($value) { return rtrim(rtrim(number_format((float)$value,1,'.',''),'0'),'.'); }
}
$midtermPages = array_chunk($midterm['subjects'],16);
foreach ($midtermPages as $midtermPage => $midtermSubjects):
?>
<article class="midterm-sheet" data-midterm-sheet data-learner-id="<?php echo midterm_escape($midterm['learner']['id']); ?>">
<div class="midterm-content">
<header class="midterm-head">
    <img class="midterm-logo" src="<?php echo midterm_escape($midterm['logo_url']); ?>" alt="<?php echo midterm_escape($midterm['school']['schname'] ?? 'School'); ?> logo">
    <div class="midterm-school"><span class="midterm-kicker">Midterm academic report</span><h1><?php echo midterm_escape($midterm['school']['schname'] ?? 'School'); ?></h1><p class="midterm-motto"><?php echo midterm_escape($midterm['school']['motto'] ?? ''); ?></p><p><?php echo midterm_escape($midterm['school']['address'] ?? ''); ?></p><p><?php echo midterm_escape(implode(' | ',array_filter([$midterm['school']['phone'] ?? '',$midterm['school']['email'] ?? '']))); ?></p></div>
    <div class="midterm-photo"><img src="<?php echo midterm_escape($midterm['learner']['passport_url']); ?>" alt="<?php echo strpos($midterm['learner']['passport_url'],'student-placeholder.svg') !== false ? 'Student photo not provided' : midterm_escape($midterm['learner']['name']).' passport'; ?>"><span>Learner photograph</span></div>
</header>
<section class="midterm-identity" aria-label="Learner details"><div class="midterm-name"><small>Learner</small><strong><?php echo midterm_escape($midterm['learner']['name']); ?></strong><span><?php echo midterm_escape($midterm['learner']['id']); ?></span></div><div><small>Recorded class</small><strong><?php echo midterm_escape($midterm['class_name']); ?></strong><span><?php echo midterm_escape($midterm['learner']['gender']); ?><?php if (!empty($midterm['learner']['dob']) && $midterm['learner']['dob'] !== '0000-00-00'): ?> · DOB: <?php echo midterm_escape($midterm['learner']['dob']); ?><?php endif; ?></span></div><div><small>Academic term</small><strong><?php echo midterm_escape($midterm['term']); ?></strong><span>Assessment period: Weeks 1-6</span></div><div><small>Class teacher</small><strong><?php echo midterm_escape($midterm['teacher'] ?: 'Not assigned'); ?></strong><span><?php echo (int)$midterm['population']; ?> learners with records</span></div></section>
<div class="midterm-body">
<section class="midterm-results" aria-label="Weekly assessment scores"><div class="midterm-section-title"><h2>Weekly assessment record</h2><span>Each week /10 · Midterm total /30</span></div><table><thead><tr><th rowspan="2" class="subject-heading">Subject</th><th colspan="6">Weekly scores (10 marks each)</th><th rowspan="2">Total<br>/30</th><th rowspan="2">Grade</th><th rowspan="2" class="remark-heading">Remark</th></tr><tr><?php for ($week=1;$week<=6;$week++): ?><th>W<?php echo $week; ?></th><?php endfor; ?></tr></thead><tbody>
<?php foreach ($midtermSubjects as $subject): ?><tr><th scope="row"><?php echo midterm_escape($subject['name']); ?></th><?php foreach ($subject['weeks'] as $score): ?><td<?php echo $score === null ? ' class="not-recorded"' : ''; ?>><?php echo $score === null ? '-' : midterm_mark($score); ?></td><?php endforeach; ?><td class="midterm-total"><?php echo midterm_mark($subject['total']); ?></td><td class="midterm-grade"><?php echo $subject['grade']; ?></td><td class="midterm-remark"><?php echo $subject['remark']; ?></td></tr><?php endforeach; ?>
</tbody></table><p class="midterm-calculation">Midterm total = (Week 1 + Week 2 + Week 3 + Week 4 + Week 5 + Week 6) ÷ 2. A dash means no score was recorded; it contributes zero to the total.</p></section>
<aside class="midterm-summary" aria-label="Report summary"><span class="midterm-kicker">At a glance</span><div class="midterm-average"><strong><?php echo number_format($midterm['average'],1); ?><small>%</small></strong><span>Overall average</span></div><div class="midterm-summary-line"><span>Marks obtained</span><strong><?php echo midterm_mark($midterm['total']); ?> / <?php echo (int)$midterm['maximum']; ?></strong></div><div class="midterm-summary-line"><span>Overall grade</span><strong><?php echo $midterm['grade']; ?></strong></div><div class="midterm-summary-line"><span>Subjects</span><strong><?php echo count($midterm['subjects']); ?></strong></div><div class="midterm-summary-line"><span>Unrecorded entries</span><strong><?php echo (int)$midterm['missing']; ?></strong></div><h3>Grading guide</h3><table class="midterm-grade-guide"><tbody><?php foreach ([['A','22.5-30','Excellent'],['B','19.5-22.4','Very Good'],['C','15-19.4','Moderate'],['D','13.5-14.9','Fair'],['E','12-13.4','Needs Help'],['F','0-11.9','Needs Help']] as $grade): ?><tr><th><?php echo $grade[0]; ?></th><td><?php echo $grade[1]; ?></td><td><?php echo $grade[2]; ?></td></tr><?php endforeach; ?></tbody></table></aside>
</div>
<footer class="midterm-report-footer"><div><small>Class teacher</small><strong><?php echo midterm_escape($midterm['teacher'] ?: '______________________'); ?></strong></div><div class="midterm-authorised"><?php if ($midterm['signature_url']): ?><img src="<?php echo midterm_escape($midterm['signature_url']); ?>" alt="Authorised signature"><?php endif; ?><small>Authorised by</small><strong><?php echo midterm_escape($midterm['school']['proprietor'] ?? 'School administration'); ?></strong></div><div class="midterm-document-meta"><span>Generated <?php echo (new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos')))->format('j M Y'); ?></span><span><?php echo midterm_escape($midterm['learner']['id']); ?> · Sheet <?php echo $midtermPage+1; ?> of <?php echo count($midtermPages); ?></span></div></footer>
</div>
</article>
<?php endforeach; ?>
